      "source": "import { display, ports } from "@getspur/spurlab-sdk";
import { tableFromIPC } from "npm:apache-arrow@21.1.0";

const PERSPECTIVE_VERSION = "4.5.1";
const EMPTY_TEXT = "Ask the agent for a symbol, file, or change to push graph evidence.";

type EvidencePort = {
  name: string;
  rows: Record<string, any>[];
  status: string;
  version: number | null;
  bytes: number;
  message: string;
};

function esc(value: unknown): string {
  return String(value ?? "").replace(/[&<>"']/g, (ch) => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;",
  }[ch] ?? ch));
}

function jsonScript(value: unknown): string {
  return JSON.stringify(value).replace(/</g, "\\u003c").replace(/>/g, "\\u003e").replace(/&/g, "\\u0026");
}

function normalizeValue(value: any): any {
  if (value === null || value === undefined) return null;
  if (typeof value === "bigint") {
    const asNumber = Number(value);
    return Number.isSafeInteger(asNumber) ? asNumber : value.toString();
  }
  if (typeof value?.toJSON === "function") return normalizeValue(value.toJSON());
  if (Array.isArray(value)) return value.map(normalizeValue);
  if (typeof value === "object") {
    const output: Record<string, unknown> = {};
    for (const [key, item] of Object.entries(value)) output[key] = normalizeValue(item);
    return output;
  }
  return value;
}

function tableRows(table: any): Record<string, any>[] {
  if (!table || typeof table.toArray !== "function") return [];
  return table.toArray().map((row: any) => normalizeValue(row));
}

async function readEvidencePort(name: string): Promise<EvidencePort> {
  try {
    const data = await ports.read(name);
    if (data.kind !== "arrow") {
      return {
        name,
        rows: [],
        status: "not_arrow",
        version: data.version,
        bytes: data.bytes.byteLength,
        message: `${name} is ${data.kind}, not Arrow IPC`,
      };
    }
    const table = tableFromIPC(data.bytes);
    const rows = tableRows(table);
    return {
      name,
      rows,
      status: rows.length ? "ok" : "empty",
      version: data.version,
      bytes: data.bytes.byteLength,
      message: rows.length ? "" : EMPTY_TEXT,
    };
  } catch (error) {
    return {
      name,
      rows: [],
      status: "missing",
      version: null,
      bytes: 0,
      message: error instanceof Error ? error.message : String(error),
    };
  }
}

function fmtInt(value: unknown): string {
  const n = Number(value ?? 0);
  return Number.isFinite(n) ? Math.round(n).toLocaleString("en-US") : "0";
}

function fmtNumber(value: unknown, digits = 3): string {
  const n = Number(value);
  return Number.isFinite(n) ? n.toFixed(digits) : "-";
}

function shortId(value: unknown): string {
  const s = String(value ?? "");
  if (!s) return "-";
  return s.length > 20 ? `${s.slice(0, 10)}...${s.slice(-6)}` : s;
}

function labelFor(row: Record<string, any>): string {
  return String(row.entity_name || row.qualified_name || shortId(row.stable_symbol_id));
}

function nodeFill(kind: unknown): string {
  const value = String(kind || "").toLowerCase();
  if (value.includes("function") || value.includes("method")) return "#2bd1a3";
  if (value.includes("struct") || value.includes("class") || value.includes("enum")) return "#66c7ff";
  if (value.includes("module") || value.includes("file")) return "#b48cff";
  if (value.includes("constant")) return "#f1b45a";
  return "#9aa5ad";
}

function statusClass(port: EvidencePort): string {
  if (port.status === "ok") return "ok";
  if (port.status === "missing" || port.status === "empty") return "idle";
  return "warn";
}

function portLine(port: EvidencePort): string {
  return port.status === "ok" ? `v${port.version} / ${fmtInt(port.rows.length)} rows` : port.status;
}

const subgraph = await readEvidencePort("subgraph");
const scorecard = await readEvidencePort("scorecard");
const analystRows = await readEvidencePort("analyst_rows");
const cochange = await readEvidencePort("cochange");
const portState = [subgraph, scorecard, analystRows, cochange];

const rawSubgraphRows = subgraph.rows;
const edgeRows = rawSubgraphRows.filter((row) => row.row_kind === "edge" || row.source_stable_id || row.target_stable_id);
const nodeRows = rawSubgraphRows.filter((row) => row.row_kind === "node" || (row.stable_symbol_id && !row.source_stable_id && !row.target_stable_id));
const nodesById = new Map<string, Record<string, any>>();
for (const row of nodeRows) {
  const id = String(row.stable_symbol_id || "");
  if (id) nodesById.set(id, row);
}
for (const edge of edgeRows) {
  for (const endpoint of [edge.source_stable_id, edge.target_stable_id]) {
    const id = String(endpoint || "");
    if (id && !nodesById.has(id)) {
      nodesById.set(id, { stable_symbol_id: id, entity_name: shortId(id), symbol_kind: "external", depth: edge.depth ?? 1 });
    }
  }
}

const nodes = Array.from(nodesById.values()).slice(0, 90);
const positioned = nodes.map((node, index) => {
  const width = 960;
  const height = 600;
  const cx = width / 2;
  const cy = height / 2;
  const depth = Math.max(0, Math.min(5, Number(node.depth ?? 0)));
  const peers = nodes.filter((item) => Number(item.depth ?? 0) === Number(node.depth ?? 0));
  const peerIndex = Math.max(0, peers.findIndex((item) => item.stable_symbol_id === node.stable_symbol_id));
  const angle = peers.length <= 1 ? -Math.PI / 2 + index * 0.17 : (Math.PI * 2 * peerIndex) / peers.length - Math.PI / 2;
  const radius = depth === 0 ? 0 : Math.min(290, 88 + depth * 70);
  return { ...node, x: cx + Math.cos(angle) * radius, y: cy + Math.sin(angle) * radius };
});
const positionedById = new Map(positioned.map((node) => [String(node.stable_symbol_id), node]));
const graphEdges = edgeRows.slice(0, 220).map((edge) => {
  const source = positionedById.get(String(edge.source_stable_id || ""));
  const target = positionedById.get(String(edge.target_stable_id || ""));
  if (!source || !target) return "";
  const hot = Boolean(edge.is_shortest_path);
  const dynamic = String(edge.edge_kind || "") === "calls_dyn";
  const stroke = hot ? "#f1b45a" : dynamic ? "#ff6b6b" : "#355767";
  return `<line x1="${source.x.toFixed(1)}" y1="${source.y.toFixed(1)}" x2="${target.x.toFixed(1)}" y2="${target.y.toFixed(1)}" stroke="${stroke}" stroke-width="${hot ? 2.6 : 1.2}" opacity="${hot ? 0.95 : 0.7}"><title>${esc(edge.edge_kind || edge.relation || "edge")}</title></line>`;
}).join("");
const graphNodes = positioned.map((node) => {
  const selected = Number(node.depth ?? 0) === 0;
  const radius = selected ? 18 : 12;
  const label = labelFor(node).slice(0, 30);
  return `<g class="cg-node"><circle cx="${node.x.toFixed(1)}" cy="${node.y.toFixed(1)}" r="${radius}" fill="${nodeFill(node.symbol_kind)}" stroke="${selected ? "#f7fbff" : "#091014"}" stroke-width="${selected ? 2.5 : 1.4}"><title>${esc(labelFor(node))}\n${esc(node.file_path || shortId(node.stable_symbol_id))}</title></circle><text x="${node.x.toFixed(1)}" y="${(node.y + radius + 15).toFixed(1)}" text-anchor="middle">${esc(label)}</text></g>`;
}).join("");
const topology = nodes.length
  ? `<svg class="cg-topology" viewBox="0 0 960 600" role="img" aria-label="Code graph topology"><defs><radialGradient id="cg-bg" cx="50%" cy="50%" r="66%"><stop offset="0" stop-color="#162126"/><stop offset="1" stop-color="#080b0e"/></radialGradient></defs><rect width="960" height="600" fill="url(#cg-bg)"></rect><g class="cg-rings"><circle cx="480" cy="300" r="88"></circle><circle cx="480" cy="300" r="158"></circle><circle cx="480" cy="300" r="228"></circle><circle cx="480" cy="300" r="290"></circle></g>${graphEdges}${graphNodes}</svg>`
  : `<div class="cg-empty"><strong>No graph evidence yet</strong><span>${esc(subgraph.message || EMPTY_TEXT)}</span></div>`;

const primaryScore = scorecard.rows[0] ?? null;
const selectedNode = positioned.find((node) => Number(node.depth ?? 0) === 0) ?? positioned[0];
const selectedLabel = primaryScore?.qualified_name || primaryScore?.entity_name || (selectedNode ? labelFor(selectedNode) : "No symbol selected");
const selectedFile = primaryScore?.file_path || selectedNode?.file_path || "-";
const edgeKinds = Array.from(new Set(edgeRows.map((row) => String(row.edge_kind || row.relation || "edge")).filter(Boolean))).sort();

const perspectivePayload = {
  blast: analystRows.rows.map((row) => ({
    entity_name: String(row.entity_name || ""),
    symbol_kind: String(row.symbol_kind || ""),
    caller_count: Number(row.caller_count ?? 0),
    hot_caller_count: Number(row.hot_caller_count ?? 0),
    caller_churn_90d: Number(row.caller_churn_90d ?? 0),
    blast_radius_score: Number(row.blast_radius_score ?? 0),
    file_path: String(row.file_path || ""),
    stable_symbol_id: String(row.stable_symbol_id || ""),
  })),
  scorecard: scorecard.rows.map((row) => ({
    entity_name: String(row.entity_name || ""),
    qualified_name: String(row.qualified_name || ""),
    symbol_kind: String(row.symbol_kind || ""),
    pagerank: Number(row.pagerank ?? 0),
    in_degree: Number(row.in_degree ?? 0),
    out_degree: Number(row.out_degree ?? 0),
    callers: Number(row.callers ?? 0),
    churn_90d: Number(row.churn_90d ?? 0),
    posture: String(row.posture || ""),
    file_path: String(row.file_path || ""),
  })),
  nodes: nodes.map((node) => ({
    depth: Number(node.depth ?? 0),
    entity_name: labelFor(node),
    symbol_kind: String(node.symbol_kind || ""),
    qualified_name: String(node.qualified_name || ""),
    file_path: String(node.file_path || ""),
    stable_symbol_id: String(node.stable_symbol_id || ""),
  })),
  edges: edgeRows.map((edge) => ({
    depth: Number(edge.depth ?? 0),
    edge_kind: String(edge.edge_kind || ""),
    relation: String(edge.relation || ""),
    source_stable_id: String(edge.source_stable_id || ""),
    target_stable_id: String(edge.target_stable_id || ""),
    confidence: String(edge.confidence || ""),
    bind_method: String(edge.bind_method || ""),
    is_shortest_path: Boolean(edge.is_shortest_path),
  })),
  cochange: cochange.rows.map((row) => ({
    file_a: String(row.file_a || ""),
    file_b: String(row.file_b || ""),
    cochange_count: Number(row.cochange_count ?? 0),
    has_static_edge: Boolean(row.has_static_edge),
  })),
};

function chip(label: string, value: string, klass = ""): string {
  return `<span class="cg-chip ${klass}"><strong>${esc(label)}</strong>${esc(value)}</span>`;
}

function kpi(label: string, value: string, accent = ""): string {
  return `<div class="cg-kpi ${accent}"><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`;
}

const statusChips = portState.map((port) => chip(port.name, portLine(port), statusClass(port))).join("");
const kindChips = edgeKinds.length ? edgeKinds.map((kind) => `<span>${esc(kind)}</span>`).join("") : `<span>${esc(EMPTY_TEXT)}</span>`;
const totalHotCallers = perspectivePayload.blast.reduce((sum, row) => sum + Number(row.hot_caller_count || 0), 0);
const maxBlast = Math.max(0, ...perspectivePayload.blast.map((row) => Number(row.blast_radius_score || 0)));

const html = `
<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@perspective-dev/viewer@${PERSPECTIVE_VERSION}/dist/css/pro-dark.css">
<style>
