ad{height:42px;display:flex;align-items:center;justify-content:space-between;gap:10px;padding:0 12px;border-bottom:1px solid #222b31;background:#11161a}.cg-pane-head h2{margin:0;color:#f6f8fa;font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:0}.cg-pane-head span{color:#829099;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.cg-left{grid-column:1;grid-row:2/4}.cg-center{grid-column:2;grid-row:2}.cg-right{grid-column:3;grid-row:2/4;border-right:0}.cg-bottom{grid-column:2;grid-row:3;display:grid;grid-template-columns:1fr 1fr;border-right:1px solid #263036}.cg-kpis{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;padding:10px}.cg-kpi{border:1px solid #263036;background:#10161a;border-radius:8px;padding:8px;min-width:0}.cg-kpi span{display:block;color:#7f8d95;font-size:10px;text-transform:uppercase;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.cg-kpi strong{display:block;color:#f6f8fa;font-size:18px;margin-top:2px;font-variant-numeric:tabular-nums;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.cg-kpi.green strong{color:#6ce6bd}.cg-kpi.amber strong{color:#f1b45a}.cg-kpi.blue strong{color:#66c7ff}.cg-kpi.coral strong{color:#ff8f8f}.cg-perspective-wrap{height:100%;min-height:0;padding:8px}.cg-left .cg-perspective-wrap{height:calc(100% - 158px)}.cg-right .cg-perspective-wrap{height:calc(100% - 270px);min-height:180px}perspective-viewer{width:100%;height:100%;border:1px solid #263036;border-radius:8px;background:#0b0f12;overflow:hidden}.cg-topology-wrap{height:100%;padding:10px;display:grid;grid-template-rows:minmax(0,1fr) 34px;gap:8px}.cg-topology{width:100%;height:100%;min-height:0;border:1px solid #263036;border-radius:8px;background:#080a0d}.cg-rings circle{fill:none;stroke:#26343c;stroke-width:1;opacity:.55}.cg-node text{fill:#dce6ea;font-size:10px;paint-order:stroke;stroke:#080a0d;stroke-width:3px;stroke-linejoin:round}.cg-legend{display:flex;align-items:center;gap:8px;min-width:0;overflow:hidden}.cg-legend span{border:1px solid #2c3940;background:#11181c;color:#b7c3c9;border-radius:999px;padding:3px 8px;white-space:nowrap}.cg-empty{height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;border:1px dashed #3a474f;border-radius:8px;color:#a8b4ba;background:#0d1215}.cg-empty strong{color:#f1b45a;margin-bottom:4px}.cg-detail{padding:12px;display:grid;gap:10px}.cg-symbol{border-bottom:1px solid #263036;padding-bottom:10px;min-width:0}.cg-symbol h3{margin:0 0 5px;color:#f6f8fa;font-size:14px;line-height:1.3;overflow-wrap:anywhere}.cg-symbol div{color:#8998a0;overflow-wrap:anywhere}.cg-score-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}@media (max-width:1100px){.cg-app{grid-template-columns:280px minmax(420px,1fr);grid-template-rows:58px minmax(360px,1fr) 300px 280px}.cg-topbar{grid-column:1/3;grid-template-columns:280px minmax(0,1fr)}.cg-status{display:none}.cg-left{grid-column:1;grid-row:2/4}.cg-center{grid-column:2;grid-row:2}.cg-bottom{grid-column:2;grid-row:3}.cg-right{grid-column:1/3;grid-row:4;border-right:0}.cg-right .cg-perspective-wrap{height:calc(100% - 130px)}}@media (max-width:780px){.cg-app{position:fixed;grid-template-columns:1fr;grid-template-rows:58px 360px 360px 320px 360px;overflow:auto}.cg-topbar{position:sticky;top:0;z-index:5;grid-column:1;grid-template-columns:1fr}.cg-brand{border-right:0}.cg-target{display:none}.cg-left,.cg-center,.cg-right,.cg-bottom{grid-column:1;grid-row:auto}.cg-bottom{grid-template-columns:1fr;grid-template-rows:1fr 1fr}.cg-pane{border-right:0}.cg-left .cg-perspective-wrap,.cg-right .cg-perspective-wrap{height:calc(100% - 128px)}}
</style>
<section class="cg-app" data-wb="workbench">
  <header class="cg-topbar">
    <div class="cg-brand"><div class="cg-mark"></div><div class="cg-title"><h1>Code Graph Workbench</h1><div>Perspective ${esc(PERSPECTIVE_VERSION)} / ${esc(portState.map(portLine).join(" / "))}</div></div></div>
    <div class="cg-target"><strong>${esc(selectedLabel)}</strong><span>${esc(selectedFile)}</span></div>
